import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { tmpdir } from 'node:os';
import { mkdtemp, writeFile, rm } from 'node:fs/promises';
import path from 'node:path';
import { parseShellRunbook } from '../../src/replay.js';

const SHELL_RUNBOOK = `#!/bin/bash
# Generated by agentic-cli
# Date:  2024-01-01
# Model: gpt-4.1-mini
# Task: deploy app

set -e

# ── Task: deploy app
# Build the project
npm run build

# Run the tests
npm test

`;

describe('replay', () => {
  let tmpDir: string;
  let runbookPath: string;

  beforeEach(async () => {
    tmpDir = await mkdtemp(path.join(tmpdir(), 'replay-test-'));
    runbookPath = path.join(tmpDir, 'runbook.sh');
  });

  afterEach(async () => {
    await rm(tmpDir, { recursive: true, force: true });
  });

  it('parses a valid shell runbook into ParsedRunbook', async () => {
    await writeFile(runbookPath, SHELL_RUNBOOK, 'utf-8');
    const result = await parseShellRunbook(runbookPath);
    expect(result.task).toBe('deploy app');
    expect(result.model).toBe('gpt-4.1-mini');
    expect(result.steps).toHaveLength(2);
  });

  it('extracts commands correctly', async () => {
    await writeFile(runbookPath, SHELL_RUNBOOK, 'utf-8');
    const result = await parseShellRunbook(runbookPath);
    expect(result.steps[0].command).toBe('npm run build');
    expect(result.steps[1].command).toBe('npm test');
  });

  it('extracts reasoning from comments', async () => {
    await writeFile(runbookPath, SHELL_RUNBOOK, 'utf-8');
    const result = await parseShellRunbook(runbookPath);
    expect(result.steps[0].reasoning).toBe('Build the project');
    expect(result.steps[1].reasoning).toBe('Run the tests');
  });

  it('extracts task labels from section markers', async () => {
    await writeFile(runbookPath, SHELL_RUNBOOK, 'utf-8');
    const result = await parseShellRunbook(runbookPath);
    expect(result.steps[0].taskLabel).toBe('deploy app');
  });

  it('handles missing header fields gracefully (returns empty strings, not crash)', async () => {
    const minimal = `#!/bin/bash\nset -e\necho hello\n`;
    await writeFile(runbookPath, minimal, 'utf-8');
    const result = await parseShellRunbook(runbookPath);
    expect(result.task).toBe('Replay Session');
    expect(result.model).toBe('');
    expect(result.steps[0].command).toBe('echo hello');
  });

  it('handles runbook with no shell commands', async () => {
    const empty = `#!/bin/bash\n# Date:  2024-01-01\n# Model: test\n# Task: nothing\nset -e\n# just a comment\n`;
    await writeFile(runbookPath, empty, 'utf-8');
    const result = await parseShellRunbook(runbookPath);
    expect(result.steps).toHaveLength(0);
  });

  it('ignores bare # comment lines (no text after #)', async () => {
    const content = `#!/bin/bash\n# Date: 2024-01-01\n# Model: test\n# Task: test\nset -e\n#\n# Do something\necho hello\n`;
    await writeFile(runbookPath, content, 'utf-8');
    const result = await parseShellRunbook(runbookPath);
    expect(result.steps[0].command).toBe('echo hello');
    expect(result.steps[0].reasoning).toBe('Do something');
  });
});
